/**
 * The standard result workbook, one per kind of data. By default a workbook has ONE data sheet and no summary sheet (a
 * summary sheet only if the owner approves it later); the methodology is a separate Arabic PDF. File names are built
 * from the task, never from an id. The landing page shows a clearly labelled SAMPLE built from FAKE data (never real
 * people or companies), generated by the same code that makes a customer's file.
 */
import { formatPhoneDisplay } from "./phoneDisplay";

export type OutputKind = "comments" | "companies" | "people";

export interface OutputStandard {
  kind: OutputKind;
  titleAr: string;
  /** The one data sheet's name in the customer's workbook. */
  sheetNameAr: string;
  /** What one row is, for file names and sentences. */
  nounAr: string;
  /** The workbook has exactly this many sheets by default. */
  dataSheets: 1;
  summarySheet: false;
}

export const OUTPUT_STANDARDS: Record<OutputKind, OutputStandard> = {
  comments: { kind: "comments", titleAr: "تعليقات", sheetNameAr: "التعليقات", nounAr: "تعليق", dataSheets: 1, summarySheet: false },
  companies: { kind: "companies", titleAr: "شركات", sheetNameAr: "بيانات الشركات", nounAr: "شركة", dataSheets: 1, summarySheet: false },
  people: { kind: "people", titleAr: "صناع القرار", sheetNameAr: "بيانات المهنيين", nounAr: "سجل", dataSheets: 1, summarySheet: false },
};

const FORBIDDEN_IN_FILE_NAME = /[/\\?%*:|"<>]/g;

/** The task-based name of a delivered file: «subject - count noun - date.ext». The subject is the customer's own task words. */
export function standardFileName(input: { kind: OutputKind; subject: string; count: number; date: string; ext: "xlsx" | "csv" | "pdf" }): string {
  const standard = OUTPUT_STANDARDS[input.kind];
  const subject = String(input.subject || "").replace(FORBIDDEN_IN_FILE_NAME, "-").replace(/\s+/g, " ").trim().slice(0, 64) || standard.titleAr;
  const count = Math.max(1, Math.floor(Number(input.count) || 1));
  return `${subject} - ${count} ${standard.nounAr} - ${input.date}.${input.ext}`.replace(FORBIDDEN_IN_FILE_NAME, "-").trim();
}

