/** The payload the real workbook generator reads; the sample is built exactly like a customer's file. */
export function samplePayload(kind: OutputKind): { metadata: Record<string, unknown>; rows: Array<Record<string, string | number>> } {
  return {
    metadata: {
      platform: kind === "comments" ? "youtube" : "web",
      entityType: kind === "people" ? "people" : kind === "companies" ? "companies" : "comments",
      ...(kind === "comments" ? { socialKind: "comments" } : {}),
      title: SAMPLE_LABEL_AR,
      collectedAt: "2026-10-20T00:00:00Z",
    },
    rows: SAMPLE_ROWS[kind],
  };
}

/** Columns of the landing preview: the workbook's own header text and the fake field it shows (a subset of the real columns). */
const PREVIEW_COLUMNS: Record<OutputKind, Array<{ header: string; field: string; format?: (value: string) => string }>> = {
  comments: [
    { header: "نص التعليق", field: "comment_text" },
    { header: "الاسم المعروض", field: "author_name" },
    { header: "تاريخ ووقت النشر", field: "published_at", format: (v) => v.slice(0, 10) },
  ],
  companies: [
    { header: "اسم الشركة", field: "company_name" },
    { header: "مجال النشاط", field: "industry" },
    { header: "المدينة", field: "city" },
    { header: "الهاتف التجاري", field: "phone", format: formatPhoneDisplay },
  ],
  people: [
    { header: "اسم جهة الاتصال", field: "full_name" },
    { header: "المسمى الوظيفي", field: "job_title" },
    { header: "الشركة", field: "company_name" },
    { header: "رقم الهاتف", field: "phone" },
  ],
};

export const SAMPLE_PREVIEW_ROWS = 4;

/** The preview table the landing page shows: headers as in the workbook, the first rows of the same fake data. */
export function samplePreview(kind: OutputKind): { headers: string[]; rows: string[][] } {
  const columns = PREVIEW_COLUMNS[kind];
  return {
    headers: columns.map((c) => c.header),
    rows: SAMPLE_ROWS[kind].slice(0, SAMPLE_PREVIEW_ROWS).map((row) => columns.map((c) => {
      const value = String(row[c.field] ?? "");
      return c.format ? c.format(value) : value;
    })),
  };
}
